class Solution {
    public int subarrayBitwiseORs(int[] arr){
        Set<Integer> current=new HashSet<>(),all=new HashSet<>();
        for(int value:arr){
            Set<Integer> next=new HashSet<>();
            next.add(value);
            for(int result:current)next.add(result|value);
            current=next;
            all.addAll(current);
        }
        return all.size();
    }
}

code.kotlin:
class Solution {
    fun subarrayBitwiseORs(arr:IntArray):Int{
        var current=emptySet<Int>();
        val all=mutableSetOf<Int>();
        for(value in arr){
            val next=mutableSetOf(value);
            for(result in current)next.add(result or value);
            current=next;
            all.addAll(current)
        };
        return all.size
    }
}

code.cpp:
class Solution {
    public: int subarrayBitwiseORs(vector<int>& arr){
        unordered_set<int> current,all;
        for(int value:arr){
            unordered_set<int> next{
                value
            };
            for(int result:current)next.insert(result|value);
            current.swap(next);
            all.insert(current.begin(),current.end());
        }
        return all.size();
    }
};
